import React, { useState, useEffect } from "react";

export function ModalDialog() {
  const [isOpen, setIsOpen] = useState(false);
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") setIsOpen(false);
    };
    if (isOpen) document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [isOpen]);
  return (
    <>
      <button onClick={() => setIsOpen(true)} className="px-3.5 py-1.5 rounded-[8px] bg-primary text-primary-foreground text-xs font-medium">Open Modal</button>
      {isOpen && (
        <div role="dialog" aria-modal="true" className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm" onClick={() => setIsOpen(false)}>
          <div className="w-full max-w-md p-6 rounded-xl border border-border bg-card shadow-2xl space-y-4" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between border-b border-border pb-3"><h3 className="text-sm font-semibold text-foreground">Confirm Action</h3><button onClick={() => setIsOpen(false)}>✕</button></div>
            <p className="text-xs text-muted-foreground">Are you sure you want to proceed with this operation?</p>
            <div className="flex justify-end gap-2 pt-2"><button onClick={() => setIsOpen(false)} className="px-3 py-1.5 rounded-[8px] border border-border text-xs">Cancel</button><button onClick={() => setIsOpen(false)} className="px-3 py-1.5 rounded-[8px] bg-primary text-primary-foreground text-xs">Confirm</button></div>
          </div>
        </div>
      )}
    </>
  );
}
